// Agent 1 — Literature Search
// Fetches arXiv + Semantic Scholar + OpenAlex in parallel, normalizes, dedupes, scores, returns top-N.

const input = $input.first().json;
const topic = input['Research topic'] || input.topic || '';
const maxPapers = parseInt(input['Max papers'] || input.max_papers || 10, 10);

if (!topic || !topic.trim()) {
  throw new Error('Research topic is required.');
}

const q = encodeURIComponent(topic);
const currentYear = new Date().getFullYear();

const s2Key = (typeof process !== 'undefined' && process.env.S2_API_KEY) || '';
const oaMailto = (typeof process !== 'undefined' && process.env.OPENALEX_MAILTO) || '';

// ---- arXiv ----
const arxivP = this.helpers.httpRequest({
  method: 'GET',
  url: 'http://export.arxiv.org/api/query?search_query=all:' + q + '&start=0&max_results=30&sortBy=relevance&sortOrder=descending',
  json: false,
  returnFullResponse: false,
}).then(function (xml) {
  const entries = String(xml).split('<entry>').slice(1);
  return entries.map(function (e) {
    const get = function (tag) {
      const m = e.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)</' + tag + '>'));
      return m ? m[1].trim() : '';
    };
    const title = get('title').replace(/\s+/g, ' ');
    const summary = get('summary').replace(/\s+/g, ' ');
    const published = get('published');
    const id = get('id');
    const authorBlocks = e.match(/<author>[\s\S]*?<\/author>/g) || [];
    const authors = authorBlocks.map(function (a) {
      const m = a.match(/<name>([^<]+)<\/name>/);
      return m ? m[1] : '';
    }).filter(Boolean);
    return {
      title: title,
      abstract: summary,
      authors: authors,
      year: published ? parseInt(published.slice(0, 4), 10) : null,
      citations: null,
      url: id,
      source: 'arXiv',
      doi: null,
    };
  });
}).catch(function (e) { console.log('arXiv error:', e.message); return []; });

// ---- Semantic Scholar ----
const s2Headers = {};
if (s2Key) s2Headers['x-api-key'] = s2Key;
const s2P = this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.semanticscholar.org/graph/v1/paper/search?query=' + q + '&limit=30&fields=title,abstract,authors,year,citationCount,externalIds,url',
  headers: s2Headers,
  json: true,
}).then(function (r) {
  return (r.data || []).map(function (p) {
    return {
      title: p.title || '',
      abstract: p.abstract || '',
      authors: (p.authors || []).map(function (a) { return a.name; }),
      year: p.year,
      citations: p.citationCount,
      url: p.url,
      source: 'Semantic Scholar',
      doi: (p.externalIds && p.externalIds.DOI) || null,
    };
  });
}).catch(function (e) { console.log('S2 error:', e.message); return []; });

// ---- OpenAlex ----
let oaUrl = 'https://api.openalex.org/works?search=' + q + '&per_page=30&sort=relevance_score:desc';
if (oaMailto) oaUrl += '&mailto=' + encodeURIComponent(oaMailto);
const oaP = this.helpers.httpRequest({
  method: 'GET',
  url: oaUrl,
  json: true,
}).then(function (r) {
  return (r.results || []).map(function (p) {
    let abstract = '';
    if (p.abstract_inverted_index) {
      const positions = [];
      for (const word of Object.keys(p.abstract_inverted_index)) {
        for (const i of p.abstract_inverted_index[word]) positions.push([i, word]);
      }
      positions.sort(function (a, b) { return a[0] - b[0]; });
      abstract = positions.map(function (pair) { return pair[1]; }).join(' ');
    }
    return {
      title: p.title || p.display_name || '',
      abstract: abstract,
      authors: (p.authorships || []).map(function (a) { return a.author && a.author.display_name; }).filter(Boolean),
      year: p.publication_year,
      citations: p.cited_by_count,
      url: p.id,
      source: 'OpenAlex',
      doi: p.doi,
    };
  });
}).catch(function (e) { console.log('OpenAlex error:', e.message); return []; });

const results = await Promise.all([arxivP, s2P, oaP]);
const all = results[0].concat(results[1]).concat(results[2]);

// ---- Dedupe ----
const seen = new Map();
for (const p of all) {
  const keySrc = (p.doi || p.title || '').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 80);
  if (!keySrc) continue;
  if (!seen.has(keySrc)) {
    seen.set(keySrc, p);
  } else {
    const existing = seen.get(keySrc);
    if (!existing.citations && p.citations) existing.citations = p.citations;
    if (!existing.abstract && p.abstract) existing.abstract = p.abstract;
    if (!existing.doi && p.doi) existing.doi = p.doi;
    if (existing.source.indexOf(p.source) === -1) existing.source = existing.source + ', ' + p.source;
  }
}
const merged = Array.from(seen.values()).filter(function (p) { return p.title; });

// ---- Score & rank ----
const terms = topic.toLowerCase().split(/\s+/).filter(function (t) { return t.length > 2; });
const maxCit = Math.max.apply(null, [1].concat(merged.map(function (p) { return p.citations || 0; })));
for (const p of merged) {
  const recency = p.year ? Math.max(0, 1 - (currentYear - p.year) / 10) : 0.3;
  const cit = Math.log(1 + (p.citations || 0)) / Math.log(1 + maxCit);
  const text = ((p.title || '') + ' ' + (p.abstract || '')).toLowerCase();
  const rel = terms.length ? (terms.filter(function (t) { return text.indexOf(t) !== -1; }).length / terms.length) : 0.5;
  p._score = 0.4 * cit + 0.3 * recency + 0.3 * rel;
}
merged.sort(function (a, b) { return b._score - a._score; });

const top = merged.slice(0, maxPapers);
return top.map(function (p) { return { json: Object.assign({}, p, { topic: topic }) }; });

// Parse Gemini's JSON response and attach the originating paper's metadata.
const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text) || '{}';
const cleaned = raw.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
let summary;
try {
  summary = JSON.parse(cleaned);
} catch (e) {
  summary = { error: 'parse failed', raw: cleaned };
}

// Reach back to the originating paper via paired-item lineage.
const paper = $('1. Literature Search Agent').item.json;

return {
  json: Object.assign({}, summary, {
    _meta: {
      title: paper.title,
      authors: paper.authors,
      year: paper.year,
      citations: paper.citations,
      url: paper.url,
      source: paper.source,
      doi: paper.doi,
    },
  }),
};

// Collapse N per-paper summaries into a single item carrying the whole array.
const items = $input.all();
const summaries = items.map(function (i) { return i.json; });
const form = $('Research Form').first().json;
const topic = form['Research topic'] || form.topic || '';
return [{ json: { topic: topic, summaries: summaries, paper_count: summaries.length } }];

// Build the Gemini request body for Agent 4 (comparator).
const topic = $json.topic;
const summaries = $json.summaries;

const text = [
  'You are the Comparison Agent in a research team. Given structured summaries of N papers on a single topic, produce a comparison that helps a researcher quickly see how the papers relate.',
  '',
  'Topic: ' + topic,
  '',
  'Summaries (JSON array):',
  JSON.stringify(summaries, null, 2),
  '',
  'Return JSON with exactly these fields:',
  '{',
  '  "table_markdown": "a GitHub-flavored markdown table with columns: | Paper | Method | Dataset | Strength | Weakness | Novelty |. Use short paper labels (first author + year). One row per paper, max ~12 words per cell.",',
  '  "clusters": [ { "name": "cluster label", "papers": ["label", "label"], "common_thread": "1 sentence" } ],',
  '  "observations": "3-5 short paragraphs of cross-paper observations: trends, disagreements, evolution over time, dominant datasets, methodological tradeoffs."',
  '}',
  '',
  'Output ONLY valid JSON, no markdown fences.',
].join('\n');

return [{
  json: {
    topic: topic,
    summaries: summaries,
    geminiBody: {
      contents: [{ parts: [{ text: text }] }],
      generationConfig: { responseMimeType: 'application/json', temperature: 0.3 },
    },
  },
}];

const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text) || '{}';
const cleaned = raw.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
let comparison;
try {
  comparison = JSON.parse(cleaned);
} catch (e) {
  comparison = { error: 'parse failed', raw: cleaned };
}
return [{ json: comparison }];

const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] && $json.candidates[0].content.parts[0].text) || '{}';
const cleaned = raw.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
let hyp;
try {
  hyp = JSON.parse(cleaned);
} catch (e) {
  hyp = { error: 'parse failed', raw: cleaned };
}
return [{ json: hyp }];

// Build Report — assemble the final markdown and emit as binary for the file-writer.
const form = $('Research Form').first().json;
const topic = form['Research topic'] || form.topic || 'Unknown topic';

const agg = $('Aggregate Summaries').first().json;
const summaries = agg.summaries || [];

const comparison = $('Parse Comparison').first().json || {};
const hyp = $json || {};

const date = new Date().toISOString().slice(0, 10);

function esc(s) { return (s == null ? '' : String(s)); }
function authorLine(meta) {
  const a = (meta && meta.authors) || [];
  if (a.length === 0) return 'Unknown authors';
  if (a.length <= 4) return a.join(', ');
  return a.slice(0, 4).join(', ') + ' et al.';
}

let md = '';
md += '# Research Report: ' + topic + '\n\n';
md += '_Generated ' + date + ' by the Multi-Agent Research Assistant._\n\n';
md += '---\n\n';

md += '## 1. Literature Summary\n\n';
md += 'Reviewed **' + summaries.length + '** papers across arXiv, Semantic Scholar, and OpenAlex.\n\n';
for (const s of summaries) {
  const meta = s._meta || {};
  md += '### ' + esc(meta.title || s.title || 'Untitled') + '\n';
  md += '*' + authorLine(meta) + ' (' + esc(meta.year || 'n.d.') + ')';
  if (meta.citations != null) md += ' · ' + meta.citations + ' citations';
  md += ' · ' + esc(meta.source || '');
  if (meta.url) md += ' · [link](' + meta.url + ')';
  md += '*\n\n';
  md += '- **Problem:** ' + esc(s.problem) + '\n';
  md += '- **Method:** ' + esc(s.method) + '\n';
  md += '- **Dataset:** ' + esc(s.dataset) + '\n';
  md += '- **Architecture:** ' + esc(s.architecture) + '\n';
  md += '- **Results:** ' + esc(s.results) + '\n';
  md += '- **Limitations:** ' + esc(s.limitations) + '\n';
  md += '- **Novelty:** ' + esc(s.novelty) + '\n\n';
}

md += '## 2. Comparison\n\n';
md += (comparison.table_markdown || '_No comparison table generated._') + '\n\n';

if (comparison.clusters && comparison.clusters.length) {
  md += '### Clusters\n\n';
  for (const c of comparison.clusters) {
    md += '- **' + esc(c.name) + '** — ' + esc(c.common_thread || '') + '\n';
    md += '  - Papers: ' + (c.papers || []).join(', ') + '\n';
  }
  md += '\n';
}

if (comparison.observations) {
  md += '### Cross-paper Observations\n\n' + comparison.observations + '\n\n';
}

md += '## 3. Research Gaps\n\n';
for (const g of (hyp.research_gaps || [])) md += '- ' + esc(g) + '\n';
if (!(hyp.research_gaps && hyp.research_gaps.length)) md += '_(none identified)_\n';
md += '\n';

md += '## 4. Proposed Hypothesis\n\n';
if (hyp.hypothesis) {
  md += '> **' + esc(hyp.hypothesis.statement) + '**\n\n';
  md += esc(hyp.hypothesis.rationale) + '\n\n';
}

md += '## 5. Experiment Plan\n\n';
const ep = hyp.experiment_plan || {};
md += '**Objective:** ' + esc(ep.objective) + '\n\n';
md += '**Dataset / simulation:** ' + esc(ep.dataset_or_simulation) + '\n\n';
if ((ep.baselines || []).length) {
  md += '**Baselines:**\n';
  for (const b of ep.baselines) md += '- ' + esc(b) + '\n';
  md += '\n';
}
if ((ep.metrics || []).length) {
  md += '**Metrics:**\n';
  for (const m of ep.metrics) md += '- ' + esc(m) + '\n';
  md += '\n';
}
if ((ep.implementation_steps || []).length) {
  md += '**Implementation steps:**\n';
  ep.implementation_steps.forEach(function (step, i) { md += (i + 1) + '. ' + esc(step) + '\n'; });
  md += '\n';
}

md += '## 6. Risks & Caveats\n\n';
for (const r of (hyp.risks || [])) md += '- ' + esc(r) + '\n';
if (!(hyp.risks && hyp.risks.length)) md += '_(none identified)_\n';
md += '\n---\n\n_End of report._\n';

const safeSlug = topic.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50);
const filename = 'report-' + date + '-' + safeSlug + '.md';

const binary = await this.helpers.prepareBinaryData(Buffer.from(md, 'utf-8'), filename, 'text/markdown');

return [{
  json: { topic: topic, filename: filename, paper_count: summaries.length },
  binary: { data: binary },
}];
